  .cell.opened {
    background: #1a1a2e;
    border-color: #333;
    cursor: default;
  }
  .cell.flagged {
    background: #16213e;
    border-color: #e94560;
  }
  .cell.mine {
    background: #e94560;
    color: #fff;
    animation: pop .25s ease;
  }
  @keyframes pop {
    0% { transform: scale(.5); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
  }
  .status {
    margin-top: 12px;
    font-size: 1.1rem;
    min-height: 1.4em;
    color: #aaa;
  }
  .status.win { color: #4ecdc4; }
  .status.lose { color: #e94560; }
